// Cached for 1 hour (default revalidate behavior)
const res = await fetch('https://api.example.com/posts', {
  next: { revalidate: 3600 }
})

// Never cached — always fetch from source
const res = await fetch('https://api.example.com/posts', {
  cache: 'no-store'
})

// Cache with a tag for targeted revalidation
const res = await fetch('https://api.example.com/posts', {
  next: { tags: ['posts'] }
})
